const item = $input.item;
const raw = item.json || {};
const binaryObj = item.binary || null;
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const rawText = (raw.rawText || raw.userPrompt || raw.text || '').toString().trim();
const userPrompt = (raw.userPrompt || raw.rawText || 'Analyze media and extract anime character Visual DNA').toString().trim();
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();

const requestedMode = (raw.mode || extracted.mode || 'QUICK').toString().toUpperCase().trim();
const effective_mode = requestedMode === 'SAVE' ? 'SAVE' : 'QUICK';

if (effective_mode === 'SAVE' && !project_id) {
  throw new Error('WF-05 Error: project_id is strictly required when executing in SAVE mode (Rule 5 Project Isolation).');
}

const character_code_hint = (raw.character_code_hint || raw.character_code || extracted.character_code || null);

let modality = (raw.modality || 'image').toString().toLowerCase().trim();
let mediaUrl = raw.mediaUrl || raw.media_url || raw.url || null;

const ytRegex = /(?:https?:\/\/)?(?:www\.|m\.)?(?:youtube\.com\/(?:watch\?v=|shorts\/|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/i;
const ytMatch = (mediaUrl && mediaUrl.match(ytRegex)) || rawText.match(ytRegex);

let youtubeVideoId = null;
let visionImageUrl = mediaUrl;

if (ytMatch && ytMatch[1]) {
  modality = 'youtube';
  youtubeVideoId = ytMatch[1];
  visionImageUrl = `https://img.youtube.com/vi/${youtubeVideoId}/maxresdefault.jpg`;
  if (!mediaUrl) mediaUrl = ytMatch[0];
}

let hasBinaryAttachment = false;
let binaryMimeType = 'image/jpeg';
let binaryBase64 = null;
let binaryFileName = null;

if (binaryObj && Object.keys(binaryObj).length > 0) {
  const firstKey = Object.keys(binaryObj)[0];
  const binItem = binaryObj[firstKey];
  hasBinaryAttachment = true;
  binaryMimeType = binItem.mimeType || 'image/jpeg';
  binaryFileName = binItem.fileName || 'uploaded_media';
  if (binItem.data) { binaryBase64 = binItem.data; }
  if (binaryMimeType.startsWith('audio/')) modality = 'audio';
  else if (binaryMimeType.includes('pdf') || binaryMimeType.includes('text') || binaryMimeType.includes('document')) modality = 'document';
  else if (binaryMimeType.startsWith('image/')) modality = 'image';
}

const openAiImageUrl = visionImageUrl ? visionImageUrl : (binaryBase64 ? `data:${binaryMimeType};base64,${binaryBase64}` : 'https://img.youtube.com/vi/dQw4w9WgXcQ/maxresdefault.jpg');

const geminiParts = [
  {
    text: [
      'You are the WF-05 Multi-Modal Vision Analyzer for the AI Cinematic Anime Engine (Master Blueprint v6.5.0).',
      'Analyze the provided input and extract the anime character Visual DNA into STRICT JSON matching this exact schema:',
      '{"character_code": "CHAR_001", "name": "string", "analysis_summary": "string", "visual_dna": {"face": "string", "hair": "string", "skin": "string", "eyes": "string", "body_build": "string", "clothing": "string", "accessories": "string", "weapons": "string", "color_palette": "string", "estimated_age": "string", "distinctive_marks": "string"}}.',
      'MANDATORY REQUIREMENT: face, hair, clothing, and color_palette MUST be non-empty descriptive strings.',
      `Modality: ${modality}`,
      `Media / Reference URL: ${visionImageUrl || mediaUrl || 'attached_binary'}`,
      `Character Code Hint: ${character_code_hint || 'Auto-Assign'}`,
      `User Prompt: ${userPrompt}`
    ].join('\n')
  }
];

if (binaryBase64 && (binaryMimeType.startsWith('image/') || binaryMimeType === 'application/pdf' || binaryMimeType.startsWith('audio/'))) {
  geminiParts.push({ inline_data: { mime_type: binaryMimeType, data: binaryBase64 } });
}

return {
  json: {
    project_id, modality, mediaUrl, vision_image_url: visionImageUrl, openai_image_url: openAiImageUrl, youtube_video_id: youtubeVideoId,
    has_binary_attachment: hasBinaryAttachment, binary_file_name: binaryFileName, rawText, userPrompt, effective_mode, character_code_hint, sessionId,
    gemini_parts: geminiParts, ingested_at: $now.toISOString()
  },
  binary: binaryObj || {}
};

const base = $('Input Normalizer & Ingestion Gate').item.json;
const geminiNode = $('Primary Vision: Gemini generateContent').item.json || {};
const currentInput = $input.item.json || {};

let rawJsonText = null;
let visionProviderUsed = null;

const geminiText = geminiNode?.candidates?.[0]?.content?.parts?.[0]?.text;
if (geminiText && typeof geminiText === 'string' && geminiText.trim().length > 0) {
  rawJsonText = geminiText.trim();
  visionProviderUsed = $env.GEMINI_VISION_MODEL || $env.LLM_FALLBACK_MODEL || 'gemini-2.0-flash';
}

if (!rawJsonText) {
  const openAiText = currentInput?.choices?.[0]?.message?.content;
  if (openAiText && typeof openAiText === 'string' && openAiText.trim().length > 0) {
    rawJsonText = openAiText.trim();
    visionProviderUsed = $env.OPENAI_VISION_MODEL || 'gpt-4o';
  }
}

let parsedPayload = null;
if (rawJsonText) {
  try {
    const stripped = rawJsonText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
    parsedPayload = JSON.parse(stripped);
  } catch (err) { parsedPayload = null; }
}

const rawDna = (parsedPayload && parsedPayload.visual_dna && typeof parsedPayload.visual_dna === 'object') ? parsedPayload.visual_dna : (parsedPayload && typeof parsedPayload === 'object' ? parsedPayload : null);

const hasMandatoryFields = Boolean(
  rawDna &&
  typeof rawDna.face === 'string' && rawDna.face.trim().length > 0 &&
  typeof rawDna.hair === 'string' && rawDna.hair.trim().length > 0 &&
  typeof rawDna.clothing === 'string' && rawDna.clothing.trim().length > 0 &&
  typeof rawDna.color_palette === 'string' && rawDna.color_palette.trim().length > 0
);

if (!hasMandatoryFields) {
  return {
    json: {
      ...base, provider_failure: true, vision_provider_used: 'NONE_FAILED',
      failure_reason: 'Both Gemini Vision and OpenAI Vision failed or returned incomplete mandatory Visual DNA fields.',
      manual_review_record: {
        project_id: base.project_id, status: 'MANUAL_REVIEW', action_type: 'VISION_ANALYSIS', review_type: 'VISION_PROVIDER_FAIL',
        action_payload: { modality: base.modality, mediaUrl: base.mediaUrl, vision_image_url: base.vision_image_url, userPrompt: base.userPrompt, character_code_hint: base.character_code_hint, failed_at: $now.toISOString() }
      }
    }
  };
}

const normalizedVisualDna = {
  face: rawDna.face.toString().trim(), hair: rawDna.hair.toString().trim(),
  skin: (rawDna.skin || 'Fair warm anime skin tone').toString().trim(), eyes: (rawDna.eyes || 'Sharp expressive anime eyes').toString().trim(),
  body_build: (rawDna.body_build || rawDna.body || 'Lean athletic anime build').toString().trim(), clothing: rawDna.clothing.toString().trim(),
  accessories: (rawDna.accessories || 'None').toString().trim(), weapons: (rawDna.weapons || 'None').toString().trim(),
  color_palette: rawDna.color_palette.toString().trim(), estimated_age: (rawDna.estimated_age || rawDna.age || '18-22 years').toString().trim(),
  distinctive_marks: (rawDna.distinctive_marks || 'None').toString().trim()
};

const resolvedCharCode = (base.character_code_hint || parsedPayload.character_code || 'CHAR_001').toString().toUpperCase().trim();
const resolvedCharName = (parsedPayload.name || resolvedCharCode).toString().trim();

return {
  json: {
    ...base, provider_failure: false, vision_provider_used: visionProviderUsed,
    character_code: resolvedCharCode, character_name: resolvedCharName,
    analysis_summary: (parsedPayload.analysis_summary || parsedPayload.summary || `Extracted Visual DNA for ${resolvedCharName} (${resolvedCharCode})`).toString().trim(),
    visual_dna: normalizedVisualDna
  }
};

const ctx = $('Vision Response Normalizer & JSON Parser').item.json;
const expiresAt = new Date(Date.now() + 3600 * 1000).toISOString();
const tempAssetUrl = `${$env.SUPABASE_URL || 'https://storage.anime-engine.internal'}/storage/v1/object/temp-working/${ctx.sessionId}/${ctx.character_code}_preview.json?expires=${encodeURIComponent(expiresAt)}`;

return {
  json: {
    ...ctx, branch_executed: 'QUICK_PREVIEW_ONLY', db_writes_performed: false,
    reference_version: null, valid_from_episode: null, valid_to_episode: null,
    working_storage_url: tempAssetUrl, working_link_expires_at: expiresAt
  }
};

const ctx = $('Vision Response Normalizer & JSON Parser').item.json;
const lookupResp = $input.item.json;
const existingRow = Array.isArray(lookupResp) ? lookupResp[0] : (lookupResp && lookupResp.character_code ? lookupResp : null);
const currentVersion = existingRow && existingRow.reference_version ? Number(existingRow.reference_version) : 0;
const nextReferenceVersion = currentVersion + 1;

const characterUpsertPayload = {
  project_id: ctx.project_id, character_code: ctx.character_code, name: existingRow?.name || ctx.character_name,
  visual_dna: ctx.visual_dna, reference_version: nextReferenceVersion, source: 'VISION_PIPELINE', validation_status: 'APPROVED'
};

const referenceHistoryPayload = {
  project_id: ctx.project_id, character_code: ctx.character_code, reference_version: nextReferenceVersion,
  visual_dna: ctx.visual_dna, valid_from_episode: 0, valid_to_episode: null, reason: 'WF-05 Vision Pipeline Extraction'
};

return {
  json: {
    ...ctx, branch_executed: 'SAVE_PERSISTED', db_writes_performed: true,
    previous_reference_version: currentVersion > 0 ? currentVersion : null, reference_version: nextReferenceVersion,
    valid_from_episode: 0, valid_to_episode: null, character_upsert_payload: characterUpsertPayload, reference_history_payload: referenceHistoryPayload
  }
};

const parserState = $('Vision Response Normalizer & JSON Parser').item.json;

if (parserState.provider_failure === true) {
  const failMsg = [
    `⚠️ **WF-05: Vision Providers Failed — Queued for Manual Review!**`,
    `• **Modality:** \`${parserState.modality}\``,
    `• **Status:** \`MANUAL_REVIEW\` (\`review_type: VISION_PROVIDER_FAIL\`)`,
    `• **Action Taken:** Gemini Vision aur OpenAI Vision dono se valid Visual DNA nahi mila, isliye request \`pending_actions\` table me safe queue kar di gayi hai.`
  ].join('\n');
  return { json: { ok: false, status: 'MANUAL_REVIEW_QUEUED', workflow_name: 'WF-05', execution_id: $execution.id, project_id: parserState.project_id, modality: parserState.modality, review_type: 'VISION_PROVIDER_FAIL', output: failMsg, text: failMsg } };
}

const activeState = $('Prepare Versioned Character & R4 History').isExecuted ? $('Prepare Versioned Character & R4 History').item.json : $('QUICK Mode Branch (Zero DB Writes)').item.json;
const dna = activeState.visual_dna;
const isSaveMode = activeState.effective_mode === 'SAVE';

const dnaBreakdown = [
  `• **Face:** ${dna.face}`,
  `• **Hair:** ${dna.hair} | **Eyes:** ${dna.eyes} | **Skin:** ${dna.skin}`,
  `• **Body Build:** ${dna.body_build} | **Estimated Age:** ${dna.estimated_age}`,
  `• **Clothing:** ${dna.clothing}`,
  `• **Accessories & Weapons:** ${dna.accessories} / ${dna.weapons}`,
  `• **Color Palette:** ${dna.color_palette}`,
  `• **Distinctive Marks:** ${dna.distinctive_marks}`
].join('\n');

const modeSummary = isSaveMode
  ? `💾 **Mode: SAVE (Canonical Persistence Active)**\n• **Character Upserted:** \`${activeState.character_code}\` (${activeState.character_name})\n• **R4 Reference History:** \`reference_version = v${activeState.reference_version}\` (\`valid_from_episode = 0\`, \`valid_to_episode = null\`)\n• **Audit Log:** Recorded \`VISION_EXTRACTION_SAVED\` in \`audit_log\`.`
  : `⚡ **Mode: QUICK (Ad-Hoc Preview — Zero Database Writes)**\n• **Isolation Guarantee:** Project tables me kuch bhi write nahi kiya gaya hai.\n• **Temporary Working Link:** ${activeState.working_storage_url}\n💡 *Tip: Is Visual DNA ko permanently lock karne ke liye \`mode: SAVE\` use karein.*`;

const finalMessage = [
  `👁️ **WF-05: Multi-Modal Vision DNA Extraction Complete!**`,
  `🔍 **Modality:** \`${activeState.modality}\` | **Provider:** \`${activeState.vision_provider_used}\``,
  `📝 **Summary:** ${activeState.analysis_summary}`, ``,
  `🧬 **Extracted Visual DNA (11-Field Schema):**`, dnaBreakdown, ``, modeSummary
].join('\n');

return {
  json: {
    ok: true, status: isSaveMode ? 'VISION_EXTRACTION_SAVED' : 'QUICK_VISION_PREVIEW_READY', workflow_name: 'WF-05', execution_id: $execution.id,
    project_id: activeState.project_id, modality: activeState.modality, mode: activeState.effective_mode, db_writes_performed: activeState.db_writes_performed,
    vision_provider_used: activeState.vision_provider_used, character_code: activeState.character_code, character_name: activeState.character_name,
    reference_version: activeState.reference_version, valid_from_episode: activeState.valid_from_episode, valid_to_episode: activeState.valid_to_episode,
    working_storage_url: activeState.working_storage_url || null, visual_dna: activeState.visual_dna, output: finalMessage, text: finalMessage
  }
};

